  const JSON_FENCE = /```(?:json)?\\s*\\n?([\\s\\S]*?)```/;

  function extractJson(raw: string): Record<string, unknown> | null {
    const fenced = raw.match(JSON_FENCE);
    if (fenced) raw = fenced[1].trim();
    // find the outermost balanced object
    const start = raw.indexOf('{');
    if (start === -1) return null;
    let depth = 0, inStr = false, esc = false;
    for (let i = start; i < raw.length; i++) {
      const c = raw[i];
      if (esc) { esc = false; continue; }
      if (c === '\\\\') { esc = true; continue; }
      if (c === '"') inStr = !inStr;
      if (inStr) continue;
      if (c === '{') depth++;
      else if (c === '}') {
        depth--;
        if (depth === 0) return JSON.parse(raw.slice(start, i + 1)) as Record<string, unknown>;
      }
    }
    return null;
  }
```

The function is **`extractJson`** — defined in `packages/core/src/summarize/summarizer.ts` immediately after the `JSON_FENCE` regex. It strips a markdown ``` fence (using `JSON_FENCE`), then scans for the outermost balanced `{...}` object (respecting strings/escapes) and parses it, returning `null` if no balanced object is found.
